/**
 * Jobs left `running` by a worker that died are handed back to the queue, and the interrupted
 * attempt is not counted. The job then re-runs the same attempt number, so its simulated failures
 * and the three-attempt limit apply exactly as if the crash had not happened.
 */
export function recoverInterruptedJobs(db: DatabaseSync): void {
  const now = new Date().toISOString();
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, run_after = 0, attempts = MAX(attempts - 1, 0), updated_at = ? WHERE status = 'running'`,
  ).run(now);
}

/** Hands back the attempt that a stopping worker was in the middle of, without counting it. */
export function abandonAttempt(db: DatabaseSync, id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, run_after = 0, attempts = MAX(attempts - 1, 0), updated_at = ? WHERE id = ?`,
  ).run(new Date().toISOString(), id);
}

